import { openDB } from 'idb';

export async function initDB() {
  const db = await openDB('pacman-db', 1, {
    upgrade(upgradeDb) {
      // high_scores store
      if (!upgradeDb.objectStoreNames.contains('high_scores')) {
        const highScoreStore = upgradeDb.createObjectStore('high_scores', {
          keyPath: 'id',
          autoIncrement: true,
        });
        highScoreStore.createIndex('score_idx', 'score', { unique: false });
      }

      // settings store (singleton)
      if (!upgradeDb.objectStoreNames.contains('settings')) {
        const settingsStore = upgradeDb.createObjectStore('settings', {
          keyPath: 'id',
        });
        // Insert default settings row with id = 1
        settingsStore.add({
          id: 1,
          color_blind_mode: false,
          mute: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        });
      }
    },
    blocking() {
      // Optional: handle old connections
    },
    terminated() {
      // Optional: cleanup
    },
  });
  return db;
}

